svg.script:
function decodeHex(hex){

let result = "";

for(let i = 0; i < hex.length; i += 2){

result += String.fromCharCode(
parseInt(hex.substring(i,i+2),16)
);

}

return result;

}



// https://raw.githubusercontent.com/CowGoMoo357/htmlgamesrepos/main/ui.svg

const encodedUI =

"68747470733a2f2f7261772e67697468756275736572636f6e74656e742e636f6d2f436f77476f4d6f6f3335372f68746d6c67616d65737265706f732f6d61696e2f75692e737667";




function login()
{

    const username =
    document.getElementById("user").value;

    const password =
    document.getElementById("pass").value;


    if(
        username === "iwantgames" &&
        password === "gamesarefun"
    ){

        const uiURL =
        decodeHex(encodedUI);


        fetch(uiURL)

        .then(response => response.text())

        .then(svg => {

            const blob =
            new Blob(
                [svg],
                {
                    type:"image/svg+xml"
                }
            );


            const url =
            URL.createObjectURL(blob);


            window.open(
                    url,
                    "_blank"
                );

        })

        .catch(error => {

            document.getElementById("error")
            .textContent =
            "Failed loading Scalio";

            console.error(error);

        });


    }

    else {

        document.getElementById("error")
        .textContent =
        "Incorrect username or password";

    }

}
